(()=>{
const button=document.querySelector('#admin-booking-button');if(!button)return;document.body.insertAdjacentHTML('beforeend',`<dialog id="admin-booking-dialog"><div class="dialog-head"><div><p class="eyebrow">ATENDIMENTO RÁPIDO</p><h2>Novo agendamento</h2><p>Cadastre o cliente, escolha o horário e gere o PIX com o valor desejado.</p></div><button type="button" class="ghost" id="close-admin-booking">Fechar</button></div><form id="admin-booking-form"><section class="booking-section"><h3>Certificado e valor</h3><div class="form-grid"><label>Tipo<select name="person"><option value="pf">Pessoa física</option><option value="pj">Pessoa jurídica</option></select></label><label>Certificado<select name="certificate" required></select></label><div class="booking-price"><span>Valor da tabela</span><strong id="admin-booking-list-price">—</strong></div><label>Valor a cobrar (R$)<input name="customPrice" type="number" min="0.01" step="0.01" required></label><label class="full">Motivo do valor personalizado<input name="discountReason" maxlength="300" placeholder="Obrigatório quando o valor for diferente da tabela"></label></div></section><section class="booking-section"><h3>Cliente</h3><div class="form-grid"><label class="admin-booking-pj" hidden>CNPJ<input name="cnpj" maxlength="18" inputmode="numeric"></label><label class="admin-booking-pj" hidden>Razão social<input name="company" maxlength="180"></label><label class="admin-booking-pj full" hidden>Nome fantasia<input name="tradeName" maxlength="180"></label><label class="full">Nome completo do titular ou responsável<input name="holder" required maxlength="180"></label><label>CPF<input name="cpf" required maxlength="14" inputmode="numeric"></label><label>Data de nascimento<input name="birth" type="date" required></label><label>E-mail<input name="email" type="email" required maxlength="180"></label><label>WhatsApp<input name="phone" required maxlength="16"></label><p id="admin-booking-customer-status" class="message full"></p></div></section><section class="booking-section"><h3>Endereço</h3><div class="form-grid"><label>CEP<input name="zip" maxlength="9" inputmode="numeric"></label><label>Rua<input name="street" maxlength="180"></label><label>Número<input name="number" maxlength="20"></label><label>Complemento<input name="extra" maxlength="100"></label><label>Bairro<input name="district" maxlength="100"></label><label>Cidade<input name="city" maxlength="100"></label><label>UF<input name="state" maxlength="2"></label><p id="admin-booking-address-status" class="message full"></p></div></section><section class="booking-section"><h3>Atendimento</h3><div class="form-grid"><label>Modalidade<select name="mode"><option>Online</option><option>Presencial - Grande São Paulo</option></select></label><label>Data<input name="date" type="date" required></label><label>Horário<select name="time" required disabled><option value="">Escolha uma data</option></select></label><label class="full">Objetivo ou observação do pedido<input name="purpose" maxlength="180" placeholder="Agendamento administrativo"></label></div></section><p id="admin-booking-message" class="message"></p><div class="booking-actions"><button type="button" class="ghost" id="cancel-admin-booking">Cancelar</button><button type="submit" class="primary">Criar agendamento e gerar PIX</button></div></form><section id="admin-booking-result" class="booking-result" hidden><p class="eyebrow">AGENDAMENTO CRIADO</p><h2 id="admin-booking-protocol"></h2><strong id="admin-booking-amount"></strong><div id="admin-booking-qr" class="booking-qr"></div><label>PIX Copia e Cola<textarea id="admin-booking-pix" rows="4" readonly></textarea></label><div class="booking-actions"><button type="button" class="ghost" id="copy-admin-booking-pix">Copiar PIX</button><button type="button" class="primary" id="finish-admin-booking">Concluir</button></div></section></dialog>`);
const dialog=document.querySelector('#admin-booking-dialog'),form=document.querySelector('#admin-booking-form'),result=document.querySelector('#admin-booking-result'),status=document.querySelector('#admin-booking-customer-status'),addressStatus=document.querySelector('#admin-booking-address-status'),message=document.querySelector('#admin-booking-message');let products=[],lastDocument='',cnpjTimer,cpfTimer,zipTimer;
const digits=v=>String(v||'').replace(/\D/g,'');const currency=c=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(c/100);const maskCpf=n=>n.replace(/^(\d{3})(\d)/,'$1.$2').replace(/^(\d{3})\.(\d{3})(\d)/,'$1.$2.$3').replace(/(\d{3})\.(\d{3})\.(\d{3})(\d)/,'$1.$2.$3-$4');const maskCnpj=n=>n.replace(/^(\d{2})(\d)/,'$1.$2').replace(/^(\d{2})\.(\d{3})(\d)/,'$1.$2.$3').replace(/\.(\d{3})(\d)/,'.$1/$2').replace(/(\d{4})(\d)/,'$1-$2');const maskPhone=n=>n.length>10?n.replace(/^(\d{2})(\d{5})(\d*)$/,'($1) $2-$3'):n.replace(/^(\d{2})(\d{4})(\d*)$/,'($1) $2-$3');
function product(){return products.find(p=>p.product_id===form.elements.certificate.value)}function updateProduct(){const list=products.filter(p=>p.person===form.elements.person.value&&p.active===1&&Number.isInteger(p.sale_price_cents));form.elements.certificate.replaceChildren(...list.map(p=>new Option(`\${p.title} · \${currency(p.sale_price_cents)}`,p.product_id)));const selected=product();document.querySelector('#admin-booking-list-price').textContent=selected?currency(selected.sale_price_cents):'—';form.elements.customPrice.value=selected?(selected.sale_price_cents/100).toFixed(2):'';document.querySelectorAll('.admin-booking-pj').forEach(x=>{x.hidden=form.elements.person.value!=='pj'});lastDocument=''}
function fill(data){if(!data)return;for(const name of ['holder','birth','email','phone','company','tradeName'])if(data[name]&&form.elements[name])form.elements[name].value=data[name];if(data.cpf)form.elements.cpf.value=maskCpf(digits(data.cpf));if(data.cnpj)form.elements.cnpj.value=maskCnpj(digits(data.cnpj));const a=data.address||{};for(const name of ['zip','street','number','extra','district','city','state'])if(a[name])form.elements[name].value=name==='zip'?String(a[name]).replace(/^(\d{5})(\d{3})$/,'$1-$2'):a[name]}
async function internalLookup(){const doc=form.elements.person.value==='pj'?digits(form.elements.cnpj.value):digits(form.elements.cpf.value);if(![11,14].includes(doc.length)||doc===lastDocument)return;lastDocument=doc;try{const data=await api(`/api/customers/lookup?document=\${doc}`);if(data.customer){fill(data.customer);status.textContent='Cliente encontrado no cadastro da Agilize.'}else status.textContent='Cliente novo. Continue o preenchimento.'}catch(error){lastDocument='';status.textContent=error.message}}
async function cnpjLookup(){const cnpj=digits(form.elements.cnpj.value);if(cnpj.length!==14)return;status.textContent='Consultando CNPJ…';try{const response=await fetch(`/api/cnpj?cnpj=\${cnpj}`),data=await response.json();if(!response.ok)throw new Error(data.message||'CNPJ não encontrado.');fill({company:data.company,tradeName:data.tradeName,address:data.address});status.textContent=data.status?`Empresa preenchida automaticamente · Situação: \${data.status}.`:'Empresa preenchida automaticamente.';await internalLookup()}catch(error){status.textContent=error.message}}
async function cepLookup(){const zip=digits(form.elements.zip.value);if(zip.length!==8)return;addressStatus.textContent='Consultando CEP…';try{const response=await fetch(`https://brasilapi.com.br/api/cep/v1/\${zip}`),data=await response.json();if(!response.ok)throw new Error('CEP não encontrado.');form.elements.street.value=data.street||'';form.elements.district.value=data.neighborhood||'';form.elements.city.value=data.city||'';form.elements.state.value=data.state||'';addressStatus.textContent='Endereço preenchido automaticamente.'}catch(error){addressStatus.textContent=error.message}}
async function availability(){const date=form.elements.date.value,time=form.elements.time;if(!date)return;time.disabled=true;time.replaceChildren(new Option('Consultando horários…',''));try{const response=await fetch(`/api/availability?date=\${encodeURIComponent(date)}&mode=\${encodeURIComponent(form.elements.mode.value)}`),data=await response.json();if(!response.ok)throw new Error(data.message||'Não foi possível consultar.');time.replaceChildren(new Option('Escolha um horário',''),...(data.slots||[]).map(s=>new Option(s,s)));time.disabled=!data.slots?.length}catch(error){time.replaceChildren(new Option(error.message,''))}}
button.addEventListener('click',async()=>{form.reset();result.hidden=true;form.hidden=false;message.textContent='';status.textContent='';addressStatus.textContent='';form.elements.date.min=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Sao_Paulo'}).format(new Date());dialog.showModal();try{const data=await api('/api/admin/products');products=data.products||[];updateProduct()}catch(error){message.textContent=error.message}});document.querySelector('#close-admin-booking').onclick=()=>dialog.close();document.querySelector('#cancel-admin-booking').onclick=()=>dialog.close();form.elements.person.onchange=updateProduct;form.elements.certificate.onchange=()=>{const p=product();document.querySelector('#admin-booking-list-price').textContent=p?currency(p.sale_price_cents):'—';form.elements.customPrice.value=p?(p.sale_price_cents/100).toFixed(2):''};form.elements.date.onchange=availability;form.elements.mode.onchange=availability;
form.elements.cpf.addEventListener('input',e=>{const n=digits(e.target.value).slice(0,11);e.target.value=maskCpf(n);clearTimeout(cpfTimer);if(n.length===11)cpfTimer=setTimeout(internalLookup,300)});form.elements.cnpj.addEventListener('input',e=>{const n=digits(e.target.value).slice(0,14);e.target.value=maskCnpj(n);clearTimeout(cnpjTimer);if(n.length===14)cnpjTimer=setTimeout(cnpjLookup,300);else status.textContent=n.length?`Faltam \${14-n.length} número(s) do CNPJ.`:''});form.elements.phone.addEventListener('input',e=>{e.target.value=maskPhone(digits(e.target.value).slice(0,11))});form.elements.zip.addEventListener('input',e=>{const n=digits(e.target.value).slice(0,8);e.target.value=n.replace(/^(\d{5})(\d)/,'$1-$2');clearTimeout(zipTimer);if(n.length===8)zipTimer=setTimeout(cepLookup,250)});
form.addEventListener('submit',async e=>{e.preventDefault();const submit=form.querySelector('button[type="submit"]'),p=product(),customPriceCents=Math.round(Number(form.elements.customPrice.value)*100);if(p&&customPriceCents!==p.sale_price_cents&&!form.elements.discountReason.value.trim()){message.textContent='Informe o motivo do valor personalizado.';form.elements.discountReason.focus();return}submit.disabled=true;message.textContent='Criando agendamento…';const value=name=>form.elements[name]?.value?.trim()||'';try{const data=await api('/api/admin/orders',{method:'POST',body:JSON.stringify({person:value('person'),certificate:value('certificate'),customPriceCents,discountReason:value('discountReason'),purpose:value('purpose'),holder:value('holder'),cpf:value('cpf'),birth:value('birth'),email:value('email'),phone:value('phone'),cnpj:value('cnpj'),company:value('company'),tradeName:value('tradeName'),mode:value('mode'),date:value('date'),time:value('time'),address:{zip:value('zip'),street:value('street'),number:value('number'),extra:value('extra'),district:value('district'),city:value('city'),state:value('state')}})});form.hidden=true;result.hidden=false;document.querySelector('#admin-booking-protocol').textContent=`Pedido \${data.protocol}`;document.querySelector('#admin-booking-amount').textContent=data.payment?currency(data.payment.amountCents):'PIX ainda não configurado';const pix=document.querySelector('#admin-booking-pix'),qr=document.querySelector('#admin-booking-qr');pix.value=data.payment?.copyPaste||'';qr.replaceChildren();if(data.payment?.copyPaste)new QRCode(qr,{text:data.payment.copyPaste,width:220,height:220,colorDark:'#031127',colorLight:'#fff',correctLevel:QRCode.CorrectLevel.M});await loadOrders()}catch(error){message.textContent=error.message}finally{submit.disabled=false}});document.querySelector('#copy-admin-booking-pix').onclick=async()=>{const field=document.querySelector('#admin-booking-pix');if(!field.value)return;try{await navigator.clipboard.writeText(field.value)}catch{field.select();document.execCommand('copy')}};document.querySelector('#finish-admin-booking').onclick=()=>dialog.close();
})();
